import{_ as a,a0 as l,w as r,s as p,I as i,x as t,a1 as d,A as o,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"findmnt-尋找掛載的文件系統 | LCTT x X-CMD","titleTemplate":false,"description":"findmnt-尋找掛載的文件系統 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"findmnt-尋找掛載的文件系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"findmnt-尋找掛載的文件系統 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Linux findmnt Command To Find Mounted Filesystems","title":"findmnt-尋找掛載的文件系統","tag":"201405","desc":""},"relativePath":"201405/Linux findmnt Command To Find Mounted Filesystems.md","filePath":"[post].md"}'),s={name:"201405/Linux findmnt Command To Find Mounted Filesystems.md"};function f(u,n,h,x,g,c){const e=l("Link");return r(),p("div",null,[n[14]||(n[14]=i("h1",{id:"findmnt-尋找掛載的文件系統",tabindex:"-1"},[t("findmnt-尋找掛載的文件系統 "),i("a",{class:"header-anchor",href:"#findmnt-尋找掛載的文件系統","aria-label":"Permalink to “findmnt-尋找掛載的文件系統”"},"​")],-1)),n[15]||(n[15]=i("p",null,"命令findmnt用來查找在Linux下已經被掛載的文件系統。該命令會從/etc/fstab、/etc/mtab或者/proc/self/mountinfo中尋找指定的文件系統。",-1)),n[16]||(n[16]=i("h3",{id:"如何安裝findmnt",tabindex:"-1"},[t("如何安裝findmnt "),i("a",{class:"header-anchor",href:"#如何安裝findmnt","aria-label":"Permalink to “如何安裝findmnt”"},"​")],-1)),i("p",null,[n[1]||(n[1]=t("findmnt命令來自於util-linux-ng軟件包，這個包現在改名為util-linux。該軟件包中還包括其他一些工具，比如hwclock等。從kernel.org ftp頁面",-1)),d(e,{href:"ftp://ftp.kernel.org/pub/linux/utils/util-linux/"},{default:o(()=>[...n[0]||(n[0]=[t("下載util-linux",-1)])]),_:1}),n[2]||(n[2]=t("以安裝findmnt。",-1))]),n[17]||(n[17]=m(`<h3 id="如何在fedora下安裝findmnt" tabindex="-1">如何在Fedora下安裝findmnt <a class="header-anchor" href="#如何在fedora下安裝findmnt" aria-label="Permalink to “如何在Fedora下安裝findmnt”">​</a></h3><p>Fedora用户可以通過下面的命令安裝該軟件包：</p><pre><code>$ sudo yum install util-linux-ng
</code></pre><h3 id="findmnt默認選項" tabindex="-1">Findmnt默認選項 <a class="header-anchor" href="#findmnt默認選項" aria-label="Permalink to “Findmnt默認選項”">​</a></h3><p>如果沒有提供特定的掛載點或者設備，該命令默認會以優美的樹形結構列出所有已經被掛載的文件系統。</p><pre><code>$ findmnt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-default.png" alt="findmnt default"></p><h3 id="findmnt輪詢模式" tabindex="-1">Findmnt輪詢模式 <a class="header-anchor" href="#findmnt輪詢模式" aria-label="Permalink to “Findmnt輪詢模式”">​</a></h3><p>findmnt可以被用來監控/proc/self/mountinfo文件的變化。輪詢模式可以通過下面的命令進行調用：</p><pre><code>$ findmnt -p
</code></pre><p>或者</p><pre><code>$ findmnt --poll
</code></pre><p>/proc/self/mountinfo文件的任何變化會自動的在終端中進行更新。一開始你不會發現終端中的輸出有任何變化，如果此時你拔掉U盤再插入，變化就會出現在終端中。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-poll.png" alt="findmnt poll"></p><p>輪詢停止的時間可以通過<strong>--timeout</strong>或者<strong>--first-only</strong>選項進行限制。</p><h3 id="超時選項" tabindex="-1">超時選項 <a class="header-anchor" href="#超時選項" aria-label="Permalink to “超時選項”">​</a></h3><p>該選項可以與--pool一起使用來限制輪詢模式的時間。<strong>超時單位是毫秒</strong>。超過此時間後，findmnt不會再監控/proc/self/mountinfo文件的變化。</p><pre><code>$ findmnt --poll --timeout 6000
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-poll-timeout.png" alt="findmnt poll timeout"></p><h3 id="first-only選項" tabindex="-1">First-only選項 <a class="header-anchor" href="#first-only選項" aria-label="Permalink to “First-only選項”">​</a></h3><p>first-only選項只會監控/proc/self/mountinfo文件的第一次變化，之後該命令退出輪詢模式。第一次變化會出現在終端中，並且返回到提示符。使用此選項在終端中輸入：</p><pre><code>$ findmnt --poll --first-only
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-poll-first-only.png" alt="findmnt poll first-only"></p><h3 id="模仿df輸出的選項" tabindex="-1">模仿df輸出的選項 <a class="header-anchor" href="#模仿df輸出的選項" aria-label="Permalink to “模仿df輸出的選項”">​</a></h3><p>findmnt命令也可以用來模仿df命令的輸出。你可以參考如下的命令使用findmnt和選項<strong>--df</strong>。</p><pre><code>$ findmnt --df
</code></pre><p>或者</p><pre><code>$ findmnt -D
</code></pre><p>它會返回和<strong>df -h</strong>命令幾乎相同的輸出。</p><pre><code>$ df -h
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-imitate-df.png" alt="findmnt imitate df"></p><h3 id="findmnt-list選項" tabindex="-1">Findmnt list選項 <a class="header-anchor" href="#findmnt-list選項" aria-label="Permalink to “Findmnt list選項”">​</a></h3><p>如果你不喜歡默認的樹形輸出，你可以使用<strong>--list</strong>或者<strong>-l</strong>選項。它會以列的形式進行輸出。</p><pre><code>$ findmnt --list
</code></pre><p>執行此命令的輸出如下：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-list.png" alt="findmnt list"></p><h3 id="findmnt-evaluate-選項" tabindex="-1">Findmnt Evaluate 選項 <a class="header-anchor" href="#findmnt-evaluate-選項" aria-label="Permalink to “Findmnt Evaluate 選項”">​</a></h3><p>求值選項會轉換所有的標籤(比如LABEL，UUID，PARTUUID或者PARTLABEL)成真實的設備名稱。該選項可以結合<strong>--fstab</strong>選項來打印所有在/etc/fstab中包含的文件系統。<strong>--fstab</strong>選項的輸出是列的形式，因此當使用<strong>--fstab</strong>的時候無需使用<strong>--list</strong>選項。</p><pre><code>$ findmnt --fstab --evaluate
</code></pre><p>當這兩個選項像如下一樣結合使用的時候，輸出如下：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-fstab-evaluate.png" alt="findmnt fstab evaluate"></p><h3 id="findmnt-type-選項" tabindex="-1">Findmnt type 選項 <a class="header-anchor" href="#findmnt-type-選項" aria-label="Permalink to “Findmnt type 選項”">​</a></h3><p>該選項允許你限制打印出的文件系統。多個文件系統可以使用逗號分割進行指定。在這個實例中，該命令會搜索ext4,ext3和vfat文件系統。</p><pre><code>$ findmnt -t ext4,ext3,vfat
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/findmnt-types.png" alt="findmnt types"></p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>你可以按照你的需要嘗試不同的findmnt選項。</p><hr>`,48)),i("p",null,[n[4]||(n[4]=t("via: ",-1)),d(e,{href:"http://linoxide.com/linux-command/powerful-findmnt-command/"},{default:o(()=>[...n[3]||(n[3]=[t("http://linoxide.com/linux-command/powerful-findmnt-command/",-1)])]),_:1})]),i("p",null,[n[7]||(n[7]=t("譯者：",-1)),d(e,{href:"https://github.com/zzlyzq"},{default:o(()=>[...n[5]||(n[5]=[t("zzlyzq",-1)])]),_:1}),n[8]||(n[8]=t(" 校對：",-1)),d(e,{href:"https://github.com/wxy"},{default:o(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[11]||(n[11]=t("本文由 ",-1)),d(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[9]||(n[9]=[t("LCTT",-1)])]),_:1}),n[12]||(n[12]=t(" 原創翻譯，",-1)),d(e,{href:"http://linux.cn/"},{default:o(()=>[...n[10]||(n[10]=[t("Linux中國",-1)])]),_:1}),n[13]||(n[13]=t(" 榮譽推出",-1))])])}const F=a(s,[["render",f]]);export{y as __pageData,F as default};
